 const two=new Map(),one=new Map(),starts=[],personalStarts=[],originals=new Set(),sourceRuns=new Set(),recent=[];
 const END='\u0003',punct=/^[,;:]$/,word=/\p{L}/u;
 let words=0,sentences=0;
 const add=(map,key,value)=>{if(!map.has(key))map.set(key,[]);map.get(key).push(value);};
