   const s=candidate(firstPerson);if(!s)continue;
   let score=(s.match(motif)||[]).length+(context==='near'&&/Körper|Gesicht|Augen|Stimme|Wand|Mauer/i.test(s)?2:0);
   if(score>bestScore){best=s;bestScore=score;}
